import { uuidPattern } from './crypto.js';
import { escapeRegExp } from './string.js';

/**
 * Get a regular expression that matches a blob URL.
 * @param {string} flags Flags for `RegExp`.
 * @returns {RegExp} Regular expression.
 */
// NOTE: deliberately *not* cached. A `g`- or `y`-flagged `RegExp` carries a mutable `lastIndex`,
// so handing the same instance to multiple callers would make `test()`/`exec()` results depend on
// previous calls. Constructing a fresh pattern here is cheap next to that hazard.
const getBlobRegex = (flags = '') =>
  new RegExp(
    `\\bblob:${escapeRegExp(globalThis.location.origin)}\\/${uuidPattern.source}\\b`,
    flags,
  );

/**
 * A regular expression to match a file path. Chained extensions of tarballs like `archive.tar.gz`
 * are treated as a special case.
 */
const filePathRegEx = /(?:(.+?)\/)?(([^/]+?)(?:\.((?:[Tt][Aa][Rr]\.)?[a-zA-Z0-9]+))?)$/;

/**
 * List of MIME types that can be considered as plaintext.
 */
const textFileTypes = [
  'application/atom+xml',
  'application/javascript',
  'application/json',
  'application/ld+json',
  'application/rss+xml',
  'application/xhtml+xml',
  'application/xml',
  'application/yaml', // RFC 9512
  'image/svg+xml',
];

/**
 * Whether the given MIME type is plaintext.
 * @param {string} type MIME type.
 * @returns {boolean} Result.
 */
const isTextFileType = (type) => type.startsWith('text/') || textFileTypes.includes(type);

/**
 * Get information about a file path. If the path has no file name, like an empty string, `basename`
 * and `filename` are empty strings.
 * @param {string} path Path to be parsed.
 * @returns {{ dirname?: string, basename: string, filename: string, extension?: string }} Result.
 * @see https://www.php.net/manual/en/function.pathinfo.php
 */
const getPathInfo = (path) => {
  let end = path.length;

  // Like PHP, ignore trailing slashes, so `foo/bar/` gives `bar` rather than nothing at all. Scan
  // instead of using `/\/+$/`, which backtracks quadratically over a long run of inner slashes
  while (path[end - 1] === '/') {
    end -= 1;
  }

  const [, dirname, basename = '', filename = '', extension] =
    path.slice(0, end).match(filePathRegEx) ?? [];

  return { dirname, basename, filename, extension };
};

/**
 * Encode the given (partial) file path or file name. Since {@link encodeURIComponent} encodes
 * slashes, we need to split and join.
 * @param {string} path Original path.
 * @returns {string} Encoded path.
 */
const encodeFilePath = (path) => path.split('/').map(encodeURIComponent).join('/');
/**
 * Decode the given (partial) file path or file name.
 * @param {string} path Encoded path.
 * @returns {string} Decoded path.
 */
const decodeFilePath = (path) => decodeURIComponent(path);

/**
 * Check if the given file matches one of the unique file type specifiers.
 * @param {File} file File to be evaluated.
 * @param {string[]} specifiers List of file type specifiers.
 * @returns {boolean} Result.
 * @see https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/accept
 */
const isValidFileType = (file, specifiers) => {
  if (!specifiers.length) {
    return true;
  }

  // Lowercase the file name once rather than once per specifier.
  const fileName = file.name.toLowerCase();

  return specifiers.some((rawSpecifier) => {
    const specifier = rawSpecifier.toLowerCase();

    if (specifier.startsWith('.')) {
      return fileName.endsWith(specifier);
    }

    const [type, subtype] = specifier.split('/');

    if (subtype === '*') {
      return file.type.split('/')[0] === type;
    }

    return file.type === specifier;
  });
};

/**
 * Scan local files in nested folders and return them in a flat array, sorted by name.
 * @param {DataTransfer} dataTransfer From `drop` event.
 * @param {object} [options] Options.
 * @param {string} [options.accept] Accepted file types, which is the same as the `accept`
 * property for HTML `<input type="file">`.
 * @returns {Promise<File[]>} Files.
 * @see https://developer.mozilla.org/en-US/docs/Web/API/DataTransferItem/webkitGetAsEntry
 */
const scanFiles = async ({ items }, { accept } = {}) => {
  const specifiers = accept
    ? accept
        .split(',')
        .map((specifier) => specifier.trim())
        .filter(Boolean)
    : [];

  /**
   * Read a file entry, resolving with `null` if the file is inaccessible.
   * @param {FileSystemFileEntry} entry File entry.
   * @returns {Promise<File | null>} File.
   */
  const getFile = (entry) =>
    new Promise((resolve) => {
      entry.file(
        resolve,
        // Skip inaccessible files
        /* v8 ignore next */
        () => resolve(null),
      );
    });

  /**
   * Read one batch of entries from a directory, resolving with an empty array if the directory is
   * unreadable so the caller doesn’t wait forever.
   * @param {FileSystemDirectoryReader} reader Directory reader.
   * @returns {Promise<FileSystemEntry[]>} Entries; empty when the directory is exhausted.
   */
  const readEntries = (reader) =>
    new Promise((resolve) => {
      reader.readEntries(
        resolve,
        /* v8 ignore next */
        () => resolve([]),
      );
    });

  /**
   * Read files recursively from the filesystem.
   * @param {FileSystemEntry} entry Either a file or directory entry.
   * @returns {Promise<File[]>} Files.
   */
  const readEntry = async (entry) => {
    // Skip hidden files
    if (entry.name.startsWith('.')) {
      return [];
    }

    if (entry.isFile) {
      const file = await getFile(/** @type {FileSystemFileEntry} */ (entry));

      return file && isValidFileType(file, specifiers) ? [file] : [];
    }

    const reader = /** @type {FileSystemDirectoryEntry} */ (entry).createReader();
    /** @type {FileSystemEntry[]} */
    const entries = [];

    // `readEntries()` returns entries in batches, so call it until it returns an empty batch
    for (;;) {
      // eslint-disable-next-line no-await-in-loop
      const batch = await readEntries(reader);

      if (!batch.length) {
        break;
      }

      entries.push(...batch);
    }

    return (await Promise.all(entries.map(readEntry))).flat();
  };

  // Get all the entries synchronously; `DataTransfer` items are cleared once the event handler
  // returns
  const entries = [...items]
    .map((item) => item.webkitGetAsEntry())
    .filter((entry) => entry !== null);

  const files = (await Promise.all(entries.map(readEntry))).flat();

  return files.sort((a, b) => a.name.localeCompare(b.name));
};

/**
 * Read the given file as plaintext. On Windows, the result may include CRLF line breaks, and some
 * legacy files use lone CR. Convert any CRLF/CR to LF to parse entries properly.
 * @param {File | Blob} file File.
 * @returns {Promise<string>} Content.
 */
const readAsText = async (file) => (await file.text()).replace(/\r\n?/g, '\n');

/**
 * Wrap the given string in a plaintext `Blob`, or return the given file as is.
 * @param {File | Blob | string} input Input file or string.
 * @returns {Blob} Blob.
 */
const toBlob = (input) =>
  typeof input === 'string' ? new Blob([input], { type: 'text/plain' }) : input;

/**
 * Get the data URL of the given input.
 * @param {File | Blob | string} input Input file or string.
 * @returns {Promise<string>} Data URL like `data:text/plain;base64,...`.
 */
const getDataURL = async (input) => {
  const blob = toBlob(input);
  const reader = new FileReader();

  return new Promise((resolve, reject) => {
    /**
     * Return the result once the content is read.
     */
    reader.onload = () => {
      resolve(/** @type {string} */ (reader.result));
    };

    /**
     * Reject the promise when the file read fails.
     */
    reader.onerror = () => {
      reject(reader.error);
    };

    reader.readAsDataURL(blob);
  });
};

/**
 * Encode the given input, either a file or a string, as a Base64-encoded string.
 * @param {File | Blob | string} input Input file or string.
 * @returns {Promise<string>} Base64.
 */
const encodeBase64 = async (input) => {
  const blob = toBlob(input);

  // Encode the bytes directly rather than going through `getDataURL()`. The data URL route holds
  // the whole Base64 payload as a string and then allocates a second full-size copy when splitting
  // off the `data:...;base64,` prefix — roughly 2× the encoded size at peak, on top of a
  // `FileReader` event-loop round trip.
  return new Uint8Array(await blob.arrayBuffer()).toBase64();
};

/**
 * Decode a Base64-encoded string as a plaintext UTF-8 string. Uses `Promise` to be consistent with
 * {@link encodeBase64}.
 * @param {string} base64 Base64-encoded string.
 * @returns {Promise<string>} Decoded string.
 * @see https://stackoverflow.com/q/21797299
 * @see https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Uint8Array/fromBase64
 */
const decodeBase64 = async (base64) => {
  const buffer = Uint8Array.fromBase64(base64);

  return new TextDecoder().decode(buffer);
};

/**
 * File extensions for MIME types whose subtype isn’t their usual extension.
 * @type {Map<string, string>}
 */
const typeExtensions = new Map([
  ['application/gzip', 'gz'],
  ['application/javascript', 'js'],
  ['application/ld+json', 'jsonld'],
  ['audio/mpeg', 'mp3'],
  ['text/javascript', 'js'],
  ['text/markdown', 'md'],
  ['text/plain', 'txt'],
  ['video/quicktime', 'mov'],
]);

/**
 * Get a file extension for the given MIME type, to name a file that has no name.
 * @param {string} type MIME type, e.g. `image/svg+xml`. Can be empty.
 * @returns {string | undefined} Extension, e.g. `svg`, or `undefined` if the type doesn’t suggest
 * one, like the generic `application/octet-stream`, or vendor-specific and experimental types such
 * as `application/vnd.ms-excel` and `application/x-tar`.
 */
const getExtensionForType = (type) => {
  // A type may carry parameters like `text/plain;charset=utf-8`
  const essence = type.toLowerCase().split(';')[0].trim();
  const mapped = typeExtensions.get(essence);

  if (mapped) {
    return mapped;
  }

  // A subtype may carry a suffix like `svg+xml`
  const subtype = essence.split('/')[1]?.split('+')[0];

  if (!subtype || /[.-]/.test(subtype)) {
    return undefined;
  }

  return subtype;
};

/**
 * Save the given file locally.
 * @param {File | Blob} file File to be saved.
 * @param {string} [name] File name. Required if the `file` param is a `Blob`.
 */
const saveFile = (file, name) => {
  const link = document.createElement('a');
  const blobURL = URL.createObjectURL(file);
  // A `Blob` may have an empty `type`
  const extension = getExtensionForType(file.type);

  link.download =
    name || /** @type {File} */ (file).name || [Date.now(), extension].filter(Boolean).join('.');
  link.href = blobURL;
  link.click();

  // Revoke asynchronously so the browser has time to initiate the download. Revoking synchronously
  // can cancel the download in some browsers (e.g. Firefox/Safari).
  globalThis.setTimeout(() => {
    URL.revokeObjectURL(blobURL);
  }, 0);
};

export {
  decodeBase64,
  decodeFilePath,
  encodeBase64,
  encodeFilePath,
  getBlobRegex,
  getDataURL,
  getPathInfo,
  isTextFileType,
  isValidFileType,
  readAsText,
  saveFile,
  scanFiles,
};
