import { MessageFormat } from 'messageformat';
import { DefaultFunctions, DraftFunctions, getLocaleDir } from 'messageformat/functions';

// Polyfill
Intl.MessageFormat ??= MessageFormat;

/**
 * A date/time format preset, extending `Intl.DateTimeFormatOptions` with a `locale` override that
 * applies whenever the preset is selected.
 * @typedef {Intl.DateTimeFormatOptions & { locale?: string }} DateFormatPreset
 */

/**
 * A number format preset, extending `Intl.NumberFormatOptions` with a `locale` override that
 * applies whenever the preset is selected.
 * @typedef {Intl.NumberFormatOptions & { locale?: string }} NumberFormatPreset
 */

/**
 * Custom format presets. Within each group, the reserved `_default` key defines the preset used
 * when no `format` option is given, replacing the bare `Intl` defaults. It also applies to the
 * matching MF2 placeholders in messages, where it likewise replaces the options the placeholder
 * resolved. Any other key defines a named preset selectable with the `format` option.
 * @typedef {object} Formats
 * @property {Record<string, NumberFormatPreset>} [number] Custom number format presets.
 * @property {Record<string, DateFormatPreset>} [date] Custom date format presets.
 * @property {Record<string, DateFormatPreset>} [time] Custom time format presets.
 * @property {Record<string, DateFormatPreset>} [datetime] Custom date/time format presets. Used
 * only by the MF2 `:datetime` function; there is no standalone `datetime()` formatter.
 */

/**
 * Per-call format overrides for the MF2 placeholders in a single message. Each entry is either the
 * name of a preset (custom or built-in) or an inline preset object.
 * @typedef {object} MessageFormats
 * @property {string | NumberFormatPreset} [number] Applied to `:number` and `:integer`.
 * @property {string | DateFormatPreset} [date] Applied to `:date`.
 * @property {string | DateFormatPreset} [time] Applied to `:time`.
 * @property {string | DateFormatPreset} [datetime] Applied to `:datetime`.
 */

/**
 * A custom MF2 function handler, registered with `registerMessageFunction()` and callable from
 * messages as `:name`.
 * @callback MessageFunction
 * @param {any} context MF2 function context, carrying `locales`, `localeMatcher` and `onError`.
 * @param {Record<string, unknown>} options Options given in the message expression, e.g.
 * `weekday=long`.
 * @param {unknown} [operand] The value the function was applied to.
 * @returns {any} A message value exposing at least `toString()`.
 * @see https://messageformat.github.io/modules/messageformat_functions.html
 */

/**
 * @callback MissingKeyHandler
 * @param {string} key The missing message key.
 * @param {string} locale The active locale.
 * @param {string | undefined} defaultValue The default value passed to `format()`, if any.
 * @returns {string | void} A replacement string, or `undefined` to fall through to the default.
 */

/**
 * @typedef {object} MessageObject
 * @property {string} id Message key.
 * @property {Record<string, any>} [values] Variables to interpolate into the message.
 * @property {string} [locale] Locale override for this call.
 * @property {string} [default] Fallback string if the key is not found.
 * @property {MessageFormats} [formats] Format overrides for the MF2 placeholders in this message.
 */

/**
 * Date/time formatting options, extending `Intl.DateTimeFormatOptions` with `locale` and `format`
 * overrides.
 * @typedef {Intl.DateTimeFormatOptions & { locale?: string, format?: string }} DateFormatOptions
 */

/**
 * Number formatting options, extending `Intl.NumberFormatOptions` with `locale` and `format`
 * overrides.
 * @typedef {Intl.NumberFormatOptions & { locale?: string, format?: string }} NumberFormatOptions
 */

// --- State ---

/** @type {string} */
let _locale = $state('');
/**
 * The locale last passed to `locale.set()`, before negotiation. Kept so the active locale can be
 * negotiated again as more locales are registered.
 */
let requestedLocale = '';
/**
 * All registered locales.
 * @type {string[]}
 */
const locales = $state([]);
/**
 * All registered resources.
 * @type {Record<string, Record<string, Intl.MessageFormat>>}
 */
const dictionary = $state({});
/**
 * Whether locale messages are currently being loaded. Returns `true` after a locale is set but
 * before its messages are available.
 * @returns {boolean} `true` if messages are pending for the current locale, `false` otherwise.
 */
const isLoading = () => !!_locale && !dictionary[_locale];

// --- Configuration state ---

/** Locale to fall back to when the active locale has no entry for a key. */
// eslint-disable-next-line padding-line-between-statements
let fallbackLocale = '';
/**
 * Negotiated fallback locale — pre-computed from `fallbackLocale` against the registered locales.
 * Cached to avoid repeated `Intl.Locale` construction on every `format()` call.
 */
let _resolvedFallback = '';
/** @type {MissingKeyHandler | undefined} */
let missingMessageHandler;
/** @type {Formats} */
let customFormats = {};
/**
 * Custom MF2 functions, keyed by the name used in messages. Read when a message is compiled, so
 * entries added after `addMessages()` do not apply to messages already registered.
 * @type {Record<string, MessageFunction>}
 */
let customFunctions = {};
/**
 * Format overrides for the MF2 placeholders of the message currently being formatted. MF2
 * formatting is synchronous, so this is set for the duration of one {@link format} call and cleared
 * again before it returns.
 * @type {MessageFormats | undefined}
 */
let messageFormats;

// --- Validation ---

/**
 * Throw a `TypeError` if the given value is not a non-empty string.
 * @param {string} label Argument label used in the error message, e.g. `addMessages: localeCode`.
 * @param {unknown} value Value to check.
 * @throws {TypeError} If `value` is not a non-empty string.
 */
const assertNonEmptyString = (label, value) => {
  if (typeof value !== 'string' || !value) {
    throw new TypeError(`${label} must be a non-empty string (got ${JSON.stringify(value)})`);
  }
};

/**
 * Throw a `TypeError` if the given value is not a string. Unlike {@link assertNonEmptyString}, an
 * empty string is accepted.
 * @param {string} label Argument label used in the error message.
 * @param {unknown} value Value to check.
 * @throws {TypeError} If `value` is not a string.
 */
const assertString = (label, value) => {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string (got ${typeof value})`);
  }
};

/**
 * Throw a `TypeError` if the given value is not a function.
 * @param {string} label Argument label used in the error message.
 * @param {unknown} value Value to check.
 * @throws {TypeError} If `value` is not a function.
 */
const assertFunction = (label, value) => {
  if (typeof value !== 'function') {
    throw new TypeError(`${label} must be a function (got ${typeof value})`);
  }
};

/**
 * Throw a `TypeError` if the given value is not a `RegExp`.
 * @param {string} label Argument label used in the error message.
 * @param {unknown} value Value to check.
 * @throws {TypeError} If `value` is not a `RegExp`.
 */
const assertRegExp = (label, value) => {
  if (!(value instanceof RegExp)) {
    throw new TypeError(`${label} must be a RegExp (got ${typeof value})`);
  }
};

// --- Messages ---

/**
 * A locale tag broken down into what locale negotiation compares.
 * @typedef {object} ParsedLocaleTag
 * @property {string} language Language subtag, such as `zh`.
 * @property {string | undefined} script Script the locale is written in, such as `Hant`. It is
 * `undefined` only for a language whose script cannot be determined, such as an unassigned code.
 * @property {string | undefined} region Region subtag the tag spells out, such as `TW`. It is
 * `undefined` for a tag that names no region, such as `zh` or `zh-Hant`.
 * @property {string | undefined} preferredRegion Region to prefer when several available locales
 * match equally well: the tag’s own region, or the one CLDR considers most likely for it, so a
 * bare `en` prefers `US` and `zh-Hant` prefers `TW`.
 * @property {boolean} anyScript Whether the tag leaves the script open, which is the case when it
 * has neither a script nor a region, such as a bare `zh`.
 */

/**
 * Parsed locale tags, keyed by the tag. `Intl.Locale` is not cheap to construct, and the same tags
 * are parsed over and over, every time a locale is registered or activated.
 *
 * A plain `Map` rather than a `SvelteMap`, because this is a pure cache of static `Intl` data that
 * nothing should react to.
 * @type {Map<string, ParsedLocaleTag | undefined>}
 */
// eslint-disable-next-line svelte/prefer-svelte-reactivity
const parsedTags = new Map();

/**
 * Parse a locale tag into the language, the script it’s written in, and the region to prefer. Both
 * are inferred from CLDR’s likely-subtags data when the tag doesn’t spell them out, so `zh-TW` is
 * parsed as Traditional Chinese and a bare `en` prefers the `US` region.
 * @param {string} tag Locale tag.
 * @returns {ParsedLocaleTag | undefined} The parsed tag, or `undefined` if it’s not a well-formed
 * BCP 47 tag.
 */
const parseLocaleTag = (tag) => {
  if (!parsedTags.has(tag)) {
    try {
      const parsed = new Intl.Locale(tag);
      const { language, script, region } = parsed;
      // `maximize()` fills in whatever the tag leaves out, so it’s only needed when something is
      // missing. It’s the expensive part of parsing, hence the cache around this whole function.
      const maximized = script && region ? undefined : parsed.maximize();

      parsedTags.set(tag, {
        language,
        script: script ?? maximized?.script,
        region,
        preferredRegion: region ?? maximized?.region,
        // A tag with neither a script nor a region, e.g. `zh`, asks for the language in whichever
        // script is available, unlike `zh-TW`, which asks for Traditional Chinese
        anyScript: !script && !region,
      });
    } catch {
      parsedTags.set(tag, undefined);
    }
  }

  return parsedTags.get(tag);
};

/**
 * Negotiate the best available locale for a requested tag.
 * 1. Exact match  2. Same language and script (en-CA → en-US)  3. Original value.
 *
 * A locale written in another script is never substituted, so Simplified Chinese (`zh-CN`) is not
 * offered to a reader of Traditional Chinese (`zh-TW`), and vice versa. Regional variants sharing a
 * script still match each other, so `pt-PT` resolves to `pt-BR`. A requested tag with neither a
 * script nor a region, such as a bare `zh`, matches a locale in any script.
 *
 * Where several available locales match a request equally well, as `en-US` and `en-GB` both do for
 * a bare `en`, the tie is broken by region:
 * 1. The region CLDR considers most likely for the request, so `en` picks `en-US` and `es` picks
 * `es-ES`, rather than whichever happened to be registered first.
 * 2. The region most likely for the language alone, which differs from the above only when the
 * request names a region that isn’t available, so `en-CA` picks `en-US` over `en-GB`.
 * 3. Registration order, so an app keeps a say where `Intl` has no opinion.
 * @param {string} requested The requested locale tag.
 * @param {string[]} available List of available locale codes.
 * @returns {string} The best-matching available locale, or `requested` if no match is found.
 */
const negotiateLocale = (requested, available) => {
  if (!requested || !available.length) return requested;
  if (available.includes(requested)) return requested;

  const parsedRequest = parseLocaleTag(requested);

  if (!parsedRequest) return requested;

  const { language, script, anyScript, preferredRegion } = parsedRequest;

  const candidates = available.filter((code) => {
    const parsed = parseLocaleTag(code);

    return !!parsed && parsed.language === language && (anyScript || parsed.script === script);
  });

  // Nothing to rank: no match at all, or no ambiguity about which match to use
  if (candidates.length < 2) return candidates[0] ?? requested;

  /**
   * Find the candidate written for the given region, if any.
   * @param {string | undefined} region Region subtag to look for.
   * @returns {string | undefined} Locale code, or `undefined` if no candidate names that region.
   */
  const findByRegion = (region) =>
    region ? candidates.find((code) => parseLocaleTag(code)?.region === region) : undefined;

  return (
    findByRegion(preferredRegion) ??
    // Only reached for a request naming a region of its own, whose own region didn’t match. Parsing
    // the bare language reuses the same cache, so this costs nothing after the first lookup.
    findByRegion(parseLocaleTag(language)?.preferredRegion) ??
    candidates[0]
  );
};

/**
 * Recursively flatten a nested message map into dot-separated keys. `{ field: { name: 'Name' } }` →
 * `{ 'field.name': 'Name' }` Top-level keys that already contain dots are preserved as-is.
 * @param {Record<string, any>} map Nested or flat message map to flatten.
 * @param {string} [prefix] Key prefix for recursive calls.
 * @returns {Record<string, string>} Flat map with dot-separated keys.
 */
const flattenMessages = (map, prefix = '') =>
  Object.entries(map).reduce((acc, [key, value]) => {
    const flatKey = prefix ? `${prefix}.${key}` : key;

    if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
      Object.assign(acc, flattenMessages(value, flatKey));
    } else {
      acc[flatKey] = value;
    }

    return acc;
  }, /** @type {Record<string, string>} */ (Object.create(null)));

/**
 * Register a locale code in `locales` (if not already present) and refresh `_resolvedFallback`.
 * Shared by {@link addMessages} and {@link register}.
 * @param {string} localeCode Locale code to register.
 */
const registerLocaleCode = (localeCode) => {
  if (!locales.includes(localeCode)) {
    locales.push(localeCode);
    _resolvedFallback = negotiateLocale(fallbackLocale, locales);
  }
};

/**
 * Resolve a requested locale against the registered locales, falling back to `fallbackLocale` when
 * no registered locale matches (only when it actually resolved to a registered locale; otherwise
 * the original value is kept).
 * @param {string} value Requested locale.
 * @returns {string} Locale to activate.
 */
const resolveLocale = (value) => {
  if (!value || !locales.length) return value;

  const resolved = negotiateLocale(value, locales);

  return !locales.includes(resolved) && _resolvedFallback && locales.includes(_resolvedFallback)
    ? _resolvedFallback
    : resolved;
};

/**
 * Re-negotiate the active locale if registering a locale changed what the one last requested with
 * `locale.set()` resolves to. That happens when it was called before the requested locale, or any
 * locale at all, was registered. Shared by {@link addMessages} and {@link register}.
 */
const renegotiateActiveLocale = () => {
  if (requestedLocale && resolveLocale(requestedLocale) !== _locale) {
    // eslint-disable-next-line no-use-before-define
    locale.set(requestedLocale);
  }
};

/**
 * Add new messages for a locale. Accepts flat or nested maps; nested objects are flattened to
 * dot-separated keys (`field.name`). Multiple dicts can be passed and are merged in order, matching
 * svelte-i18n’s `addMessages(locale, ...dicts)` signature.
 * @param {string} localeCode Locale.
 * @param {...Record<string, any>} maps One or more message maps (flat or nested).
 * @throws {TypeError} If `localeCode` is not a non-empty string or any map is not a plain object.
 * @see https://messageformat.github.io/modules/messageformat.html
 */
const addMessages = (localeCode, ...maps) => {
  assertNonEmptyString('addMessages: localeCode', localeCode);

  maps.forEach((map, i) => {
    if (map === null || typeof map !== 'object' || Array.isArray(map)) {
      throw new TypeError(
        `addMessages: maps[${i}] must be a plain object (got ${Array.isArray(map) ? 'array' : typeof map})`,
      );
    }
  });

  registerLocaleCode(localeCode);
  dictionary[localeCode] ??= {};

  const messages = dictionary[localeCode];
  // Custom functions come last so they can replace a built-in of the same name. Resolved once per
  // call: `customFunctions` cannot change while the maps below are compiled.
  // eslint-disable-next-line no-use-before-define
  const functions = { ...MESSAGE_FUNCTIONS, ...customFunctions };

  maps.forEach((map) => {
    Object.entries(flattenMessages(map)).forEach(([key, value]) => {
      messages[key] = new Intl.MessageFormat(localeCode, String(value), { functions });
    });
  });

  renegotiateActiveLocale();
};

// --- Loader ---

// Plain `Map`s rather than `SvelteMap`s, because these are private bookkeeping that nothing reacts
// to; `isLoading()` reads `dictionary` instead.
/** @type {Map<string, () => Promise<Record<string, string>>>} */
// eslint-disable-next-line svelte/prefer-svelte-reactivity
const loaderQueue = new Map();
/** @type {Map<string, Promise<void>>} */
// eslint-disable-next-line svelte/prefer-svelte-reactivity
const loaderPromises = new Map();

/**
 * Execute the registered loader for the given locale (or the current locale if omitted) and wait
 * until the messages are loaded. Subsequent calls for the same locale return the same promise.
 * @param {string} [localeCode] Defaults to `locale.current`.
 * @returns {Promise<void>}
 * @throws {TypeError} If `localeCode` is provided and is not a string.
 */
const waitLocale = (localeCode = _locale) => {
  assertString('waitLocale: localeCode', localeCode);

  if (!localeCode) return Promise.resolve();

  let promise = loaderPromises.get(localeCode);

  if (!promise) {
    const loader = loaderQueue.get(localeCode);

    promise = loader
      ? Promise.resolve(loader()).then(
          (map) => {
            addMessages(localeCode, map);
          },
          () => {
            loaderPromises.delete(localeCode);

            // If the failed `locale` is still the active one and has no `dictionary` entry, fall
            // back so that `isLoading()` does not remain `true` forever. Going through
            // `locale.set()` also triggers the fallback locale’s own loader and updates
            // `<html lang>`.
            if (
              _locale === localeCode &&
              !dictionary[localeCode] &&
              _resolvedFallback &&
              _resolvedFallback !== localeCode
            ) {
              // eslint-disable-next-line no-use-before-define
              return locale.set(_resolvedFallback);
            }

            return undefined;
          },
        )
      : Promise.resolve();

    loaderPromises.set(localeCode, promise);
  }

  return promise;
};

// --- Locale ---

/**
 * Whether the given locale (or the current locale if omitted) is written right-to-left. Reactive:
 * re-evaluates automatically whenever the locale changes.
 *
 * `getLocaleDir()` reads `Intl.Locale`’s `getTextInfo()`/`textInfo` when available (Chrome/Safari),
 * falls back to the maximized script subtag (Firefox), and returns `'auto'` for an empty or invalid
 * tag.
 * @param {string} [localeCode] Locale to check. Defaults to the active locale.
 * @returns {boolean} `true` if the locale is RTL, `false` otherwise.
 */
const isRTL = (localeCode = _locale) => getLocaleDir(localeCode) === 'rtl';

/**
 * Current locale.
 */
const locale = {
  /**
   * Returns the current locale code.
   * @returns {string} The active locale code.
   */
  get current() {
    return _locale;
  },
  /**
   * Set the current locale. Negotiates against registered locales (e.g. En-CA → en-US), updates
   * `<html lang>` / `<html dir>`, and auto-triggers any registered loader.
   * @param {string} value The locale to set.
   * @returns {Promise<void>}
   * @throws {TypeError} If `value` is not a string.
   */
  set(value) {
    assertString('locale.set: value', value);

    requestedLocale = value;

    const resolved = resolveLocale(value);

    _locale = resolved;

    if (typeof document !== 'undefined' && resolved) {
      document.documentElement.lang = resolved;

      const dir = getLocaleDir(resolved);

      // `auto` means the direction could not be determined, e.g. `resolved` is not a valid BCP 47
      // tag; leave the attribute alone in that case
      if (dir !== 'auto') {
        document.documentElement.dir = dir;
      }
    }

    return waitLocale(resolved);
  },
};

/**
 * Register a custom MF2 function, callable from messages as `:name`. Registering an existing name,
 * including a built-in like `date`, replaces it.
 *
 * Messages are compiled by {@link addMessages}, which captures the functions available at that
 * moment, so **all functions must be registered before the messages that use them are added**. A
 * message referencing an unregistered function formats as a fallback such as `{$value}`.
 * @param {string} name Function name, without the leading colon.
 * @param {MessageFunction} fn Function handler.
 * @throws {TypeError} If `name` is not a non-empty string or `fn` is not a function.
 * @see https://messageformat.github.io/modules/messageformat_functions.html
 */
const registerMessageFunction = (name, fn) => {
  assertNonEmptyString('registerMessageFunction: name', name);
  assertFunction('registerMessageFunction: fn', fn);

  customFunctions[name] = fn;
};

/**
 * Register an async loader for a locale. The loader is called the first time
 * `waitLocale(localeCode)` is invoked for that locale.
 * @param {string} localeCode Locale.
 * @param {() => Promise<Record<string, string>>} loader Function returning a message map.
 * @throws {TypeError} If `localeCode` is not a non-empty string or `loader` is not a function.
 */
const register = (localeCode, loader) => {
  assertNonEmptyString('register: localeCode', localeCode);
  assertFunction('register: loader', loader);

  loaderQueue.set(localeCode, loader);
  // Invalidate any cached promise so the new loader is picked up on next waitLocale call.
  loaderPromises.delete(localeCode);

  registerLocaleCode(localeCode);
  renegotiateActiveLocale();
};

/**
 * Get the user’s preferred locale from the browser. The browser’s preferred languages are tried in
 * order and negotiated against the registered locales, so a language further down the list wins
 * when the ones before it are unavailable — including when the first one is only unavailable in the
 * script it asks for, as for a reader of Traditional Chinese who also accepts Japanese.
 *
 * The first preferred language is returned as is when no locale is registered yet, or when none of
 * them matches; {@link locale.set} negotiates again and applies the fallback locale in that case.
 * @returns {string | undefined} A locale code, or `undefined` in non-browser environments.
 */
const getLocaleFromNavigator = () => {
  if (typeof navigator === 'undefined') return undefined;

  const languages = navigator.languages?.length ? navigator.languages : [navigator.language];

  return (
    languages
      .map((lang) => negotiateLocale(lang, locales))
      .find((code) => locales.includes(code)) ?? languages[0]
  );
};

/**
 * Shared implementation for {@link getLocaleFromHostname} and {@link getLocaleFromPathname}.
 * @param {'hostname' | 'pathname'} part Part of `window.location` to match against.
 * @param {string} label Argument label used in the error message.
 * @param {RegExp} pattern Pattern with a capture group for the locale code.
 * @returns {string | undefined} The matched locale code, or `undefined` if not in a browser or no
 * match.
 * @throws {TypeError} If `pattern` is not a `RegExp`.
 */
const getLocaleFromLocation = (part, label, pattern) => {
  assertRegExp(label, pattern);

  return typeof window === 'undefined' || !window.location
    ? undefined
    : window.location[part].match(pattern)?.[1];
};

/**
 * Shared implementation for {@link getLocaleFromQueryString} and {@link getLocaleFromHash}.
 * @param {'search' | 'hash'} part Part of `window.location` to parse as a query string.
 * @param {string} label Argument label used in the error message.
 * @param {string} key The key to read.
 * @returns {string | undefined} The parameter value, or `undefined` if not in a browser or not
 * found.
 * @throws {TypeError} If `key` is not a non-empty string.
 */
const getLocaleFromLocationParams = (part, label, key) => {
  assertNonEmptyString(label, key);

  if (typeof window === 'undefined' || !window.location) return undefined;

  // The hash may carry a leading `#`, which is not part of the query string.
  const query = part === 'hash' ? window.location.hash.replace(/^#/, '') : window.location.search;

  return new URLSearchParams(query).get(key) ?? undefined;
};

/**
 * Get the locale from a pattern matched against `window.location.hostname`.
 * @param {RegExp} hostnamePattern Pattern with a capture group for the locale code.
 * @returns {string | undefined} The matched locale code, or `undefined` if not in a browser or no
 * match.
 * @throws {TypeError} If `hostnamePattern` is not a `RegExp`.
 */
const getLocaleFromHostname = (hostnamePattern) =>
  getLocaleFromLocation('hostname', 'getLocaleFromHostname: hostnamePattern', hostnamePattern);

/**
 * Get the locale from a pattern matched against `window.location.pathname`.
 * @param {RegExp} pathnamePattern Pattern with a capture group for the locale code.
 * @returns {string | undefined} The matched locale code, or `undefined` if not in a browser or no
 * match.
 * @throws {TypeError} If `pathnamePattern` is not a `RegExp`.
 */
const getLocaleFromPathname = (pathnamePattern) =>
  getLocaleFromLocation('pathname', 'getLocaleFromPathname: pathnamePattern', pathnamePattern);

/**
 * Get the locale from a URL query string parameter.
 * @param {string} queryKey The query string key to read.
 * @returns {string | undefined} The query parameter value, or `undefined` if not in a browser or
 * not found.
 * @throws {TypeError} If `queryKey` is not a non-empty string.
 */
const getLocaleFromQueryString = (queryKey) =>
  getLocaleFromLocationParams('search', 'getLocaleFromQueryString: queryKey', queryKey);

/**
 * Get the locale from a `key=value` pair in `window.location.hash`.
 * @param {string} hashKey The key to look for in the hash.
 * @returns {string | undefined} The hash parameter value, or `undefined` if not in a browser or not
 * found.
 * @throws {TypeError} If `hashKey` is not a non-empty string.
 */
const getLocaleFromHash = (hashKey) =>
  getLocaleFromLocationParams('hash', 'getLocaleFromHash: hashKey', hashKey);

// --- Configuration ---

/**
 * Initialize the locales.
 * @param {object} args Arguments.
 * @param {string} args.fallbackLocale Locale to be used for fallback.
 * @param {string} [args.initialLocale] Locale to be used for the initial selection.
 * @param {Formats} [args.formats] Custom named formats. The reserved `_default` key in each group
 * defines the preset used when a `number()`, `date()` or `time()` call passes no `format` option,
 * and for the matching MF2 placeholders in messages. A preset may carry a `locale` to format in a
 * locale other than the active one.
 * @param {MissingKeyHandler} [args.handleMissingMessage] Called when a message key is not found.
 * May return a string to use as a fallback.
 * @throws {TypeError} If `args.fallbackLocale` is not a string, `args.initialLocale` is not a
 * string, or `args.handleMissingMessage` is not a function.
 */
const init = (args) => {
  if (!args || typeof args.fallbackLocale !== 'string') {
    throw new TypeError(
      `init: fallbackLocale must be a string (got ${JSON.stringify(args?.fallbackLocale)})`,
    );
  }

  if (args.initialLocale !== undefined) {
    assertString('init: initialLocale', args.initialLocale);
  }

  if (args.handleMissingMessage !== undefined) {
    assertFunction('init: handleMissingMessage', args.handleMissingMessage);
  }

  fallbackLocale = args.fallbackLocale;
  _resolvedFallback = negotiateLocale(fallbackLocale, locales);
  missingMessageHandler = args.handleMissingMessage;
  customFormats = args.formats ?? {};
  if (args.initialLocale) locale.set(args.initialLocale);
};

// --- Formatting ---

/**
 * Get a compiled message. Only the dictionary’s own keys are considered, so a key such as
 * `constructor` or `toString` is not resolved to an `Object.prototype` member.
 * @param {string} localeCode Locale.
 * @param {string} key Message key.
 * @returns {Intl.MessageFormat | undefined} The message, or `undefined` if not found.
 */
const getMessage = (localeCode, key) => {
  const messages = dictionary[localeCode];

  return messages && Object.hasOwn(messages, key) ? messages[key] : undefined;
};

/**
 * Get the locales to look a message up in, in order of preference: the active locale (or the given
 * override), then the fallback locale if it differs.
 * @param {string} [localeOverride] Locale override for this call.
 * @returns {string[]} One or two locale codes.
 */
const getLookupLocales = (localeOverride) => {
  const active = localeOverride ?? _locale;

  return active !== _resolvedFallback ? [active, _resolvedFallback] : [active];
};

/**
 * Format a message by key.
 *
 * Supports two call signatures (matching svelte-i18n):
 * - `format(id, options?)` — key as first argument
 * - `format({ id, values, locale, default })` — options object only.
 * @param {string | MessageObject} key Message key, or an object with `id` and options.
 * @param {{ values?: Record<string, any>, locale?: string, default?: string,
 * formats?: MessageFormats }} [options] Formatting options when `key` is a string.
 * @returns {string} The formatted message string.
 * @throws {TypeError} If `key` is `null` or `undefined`.
 */
const format = (
  key,
  { values = {}, locale: localeOverride, default: defaultString, formats } = {},
) => {
  if (key === null || key === undefined) {
    throw new TypeError(
      `format: key must be a string or message object (got ${JSON.stringify(key)})`,
    );
  }

  if (typeof key === 'object') {
    const { id, ...options } = key;

    return format(id, options);
  }

  const lookupLocales = getLookupLocales(localeOverride);
  const [active] = lookupLocales;

  // Stop at the first locale that has the message, so the fallback dictionary is read (and tracked
  // as a reactive dependency) only when needed
  const message = lookupLocales.reduce(
    (/** @type {Intl.MessageFormat | undefined} */ found, code) => found ?? getMessage(code, key),
    undefined,
  );

  messageFormats = formats;

  /** @type {string | undefined} */
  let result;

  try {
    result = message?.format(values);
  } finally {
    messageFormats = undefined;
  }

  if (result !== undefined) return result;

  if (missingMessageHandler) {
    const handled = missingMessageHandler(key, active, defaultString);

    if (handled !== undefined) return handled;
  }

  return defaultString ?? key;
};

/**
 * Return a nested object of formatted strings for all keys under the given prefix. Equivalent to
 * svelte-i18n’s `$json()`. Useful for iterating over a group of messages.
 * @param {string} prefix Key prefix (e.g. `'nav'` matches `nav.home`, `nav.about`, …).
 * @param {{ locale?: string }} [options] Lookup options.
 * @returns {Record<string, string> | undefined} Object mapping suffix keys to formatted strings, or
 * `undefined` if no keys match the prefix.
 * @throws {TypeError} If `prefix` is not a non-empty string.
 */
const json = (prefix, { locale: localeOverride } = {}) => {
  assertNonEmptyString('json: prefix', prefix);

  const pfx = `${prefix}.`;
  const result = /** @type {Record<string, string>} */ ({});

  /**
   * Format every message under the prefix into `result`, keyed by the suffix.
   * @param {Record<string, Intl.MessageFormat>} messages Messages for one locale.
   */
  const collect = (messages) => {
    Object.entries(messages).forEach(([key, mf]) => {
      if (key.startsWith(pfx)) {
        result[key.slice(pfx.length)] = mf.format({});
      }
    });
  };

  // Start with fallback entries, then overlay active so per-key fallback works.
  getLookupLocales(localeOverride)
    .reverse()
    .forEach((code) => collect(dictionary[code] ?? {}));

  return Object.keys(result).length ? result : undefined;
};

// --- Date, time & number ---

/** Reserved preset name defining the options used when no `format` option is given. */
const DEFAULT_FORMAT_KEY = '_default';

// Built-in named formats matching svelte-i18n defaults
/** @type {Record<string, DateFormatPreset>} */
const BUILT_IN_DATE_FORMATS = {
  short: { month: 'numeric', day: 'numeric', year: '2-digit' },
  medium: { month: 'short', day: 'numeric', year: 'numeric' },
  long: { month: 'long', day: 'numeric', year: 'numeric' },
  full: { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' },
};

/** @type {Record<string, DateFormatPreset>} */
const BUILT_IN_TIME_FORMATS = {
  short: { hour: 'numeric', minute: 'numeric' },
  medium: { hour: 'numeric', minute: 'numeric', second: 'numeric' },
  long: { hour: 'numeric', minute: 'numeric', second: 'numeric', timeZoneName: 'short' },
  full: { hour: 'numeric', minute: 'numeric', second: 'numeric', timeZoneName: 'short' },
};

/** @type {Record<string, NumberFormatPreset>} */
const BUILT_IN_NUMBER_FORMATS = {
  currency: { style: 'currency' },
  percent: { style: 'percent' },
  scientific: { notation: 'scientific' },
  engineering: { notation: 'engineering' },
  compactLong: { notation: 'compact', compactDisplay: 'long' },
  compactShort: { notation: 'compact', compactDisplay: 'short' },
};

/**
 * Built-in presets by kind. `datetime` has no built-ins; its names resolve from `formats.datetime`.
 * @type {Record<string, Record<string, DateFormatPreset | NumberFormatPreset>>}
 */
const BUILT_IN_FORMATS = {
  date: BUILT_IN_DATE_FORMATS,
  time: BUILT_IN_TIME_FORMATS,
  number: BUILT_IN_NUMBER_FORMATS,
};

/**
 * Look up a named preset for the given kind: a custom preset defined in `init({ formats })` first,
 * then a built-in one.
 * @param {string} kind One of `number`, `date`, `time` or `datetime`.
 * @param {string} name Preset name.
 * @returns {DateFormatPreset | NumberFormatPreset | undefined} The preset, or `undefined` if no
 * preset of that name exists for the kind.
 */
const getNamedPreset = (kind, name) =>
  customFormats[/** @type {keyof Formats} */ (kind)]?.[name] ?? BUILT_IN_FORMATS[kind]?.[name];

/**
 * Look up the group’s `_default` preset defined in `init({ formats })`.
 * @param {string} kind One of `number`, `date`, `time` or `datetime`.
 * @returns {DateFormatPreset | NumberFormatPreset | undefined} The preset, or `undefined` if none
 * is defined for the kind.
 */
const getDefaultPreset = (kind) =>
  customFormats[/** @type {keyof Formats} */ (kind)]?.[DEFAULT_FORMAT_KEY];

/**
 * Resolve the preset for a standalone {@link date}, {@link time} or {@link number} call: the named
 * preset requested with the `format` option, falling back to the group’s `_default` preset.
 * @param {'number' | 'date' | 'time'} kind One of `number`, `date` or `time`.
 * @param {string} [name] Preset name from the `format` option, if any.
 * @returns {DateFormatPreset | NumberFormatPreset} The preset, or an empty object if neither the
 * call nor `init({ formats })` provides one.
 */
const getCallPreset = (kind, name) =>
  (name ? getNamedPreset(kind, name) : undefined) ?? getDefaultPreset(kind) ?? {};

/**
 * Resolve the preset that should override an MF2 function, preferring an override passed to the
 * current {@link format} call and falling back to the group’s `_default` preset.
 * @param {string} kind One of `number`, `date`, `time` or `datetime`.
 * @returns {DateFormatPreset | NumberFormatPreset | undefined} The preset, or `undefined` when
 * neither the call nor `init({ formats })` provides one for the kind.
 */
const getMessagePreset = (kind) => {
  const spec = messageFormats?.[/** @type {keyof MessageFormats} */ (kind)];
  const preset = typeof spec === 'string' ? getNamedPreset(kind, spec) : spec;

  return preset ?? getDefaultPreset(kind);
};

/**
 * Build a replacement for an MF2 message value that formats through `formatter`. Spreading the
 * original keeps its `selectKey`, so `:number` continues to work as a plural selector.
 * @param {any} mv The message value returned by the wrapped MF2 function.
 * @param {Intl.DateTimeFormat | Intl.NumberFormat} formatter Formatter built from the preset.
 * @param {string} [presetLocale] Locale carried by the preset, if any.
 * @returns {any} The replacement message value.
 */
const overrideMessageValue = (mv, formatter, presetLocale) => {
  const value = mv.valueOf();

  return {
    // The spread carries over `selectKey` and `valueOf`, so `:number` keeps working as a plural
    // selector and the value stays usable as an operand for another function.
    ...mv,
    // `MessageFormat.format()` reads `dir` to pick the bidi isolate character, so it has to follow
    // the preset locale. `toParts()` keeps the original formatter, but it is reachable only through
    // `formatToParts()`, which this library does not expose.
    dir: presetLocale ? getLocaleDir(presetLocale) : mv.dir,
    /**
     * Format the value through the preset.
     * @returns {string} The formatted string.
     */
    toString: () => formatter.format(value),
  };
};

/**
 * Wrap an MF2 function so a preset selected for the current {@link format} call replaces the
 * options it resolved.
 * @param {any} fn The MF2 function to wrap.
 * @param {'number' | 'date' | 'time' | 'datetime'} kind Format kind to look up.
 * @param {typeof Intl.DateTimeFormat | typeof Intl.NumberFormat} Formatter Formatter to build from
 * the preset.
 * @returns {any} The wrapped function.
 */
const wrapMessageFunction =
  (fn, kind, Formatter) =>
  /**
   * Apply the preset selected for the current {@link format} call to the wrapped function’s result.
   * @param {any} ctx MF2 function context.
   * @param {any} options Options resolved by the wrapped function.
   * @param {any} operand The operand passed to the function.
   * @returns {any} The message value, with any preset applied.
   */
  (ctx, options, operand) => {
    const mv = fn(ctx, options, operand);
    const preset = getMessagePreset(kind);

    if (!preset) return mv;

    const { locale: presetLocale, ...rest } = preset;

    return overrideMessageValue(
      mv,
      new /** @type {any} */ (Formatter)(presetLocale ?? ctx.locales, rest),
      presetLocale,
    );
  };

/**
 * MF2 functions used to compile messages. `:number` and `:integer` come from `DefaultFunctions`;
 * `DraftFunctions` does not define them, and the `functions` option is layered over the defaults,
 * so wrapping the wrong source would shadow them with `undefined`. `:integer` looks up the
 * `number` presets, like `Intl.MessageFormat` itself.
 */
const MESSAGE_FUNCTIONS = {
  ...DraftFunctions,
  date: wrapMessageFunction(DraftFunctions.date, 'date', Intl.DateTimeFormat),
  time: wrapMessageFunction(DraftFunctions.time, 'time', Intl.DateTimeFormat),
  datetime: wrapMessageFunction(DraftFunctions.datetime, 'datetime', Intl.DateTimeFormat),
  number: wrapMessageFunction(DefaultFunctions.number, 'number', Intl.NumberFormat),
  integer: wrapMessageFunction(DefaultFunctions.integer, 'number', Intl.NumberFormat),
};

/**
 * Shared implementation for {@link date}, {@link time} and {@link number}: format a value with the
 * preset selected by the `format` option, overlaid with any other options given.
 * @param {typeof Intl.DateTimeFormat | typeof Intl.NumberFormat} Formatter Formatter to use.
 * @param {'number' | 'date' | 'time'} kind Format kind to look up.
 * @param {any} value The value to format.
 * @param {DateFormatOptions | NumberFormatOptions} options Formatting options.
 * @returns {string} The formatted string.
 */
const formatStandaloneValue = (Formatter, kind, value, options) => {
  const { locale: loc, format: fmt, ...rest } = options;
  const { locale: presetLocale, ...named } = getCallPreset(kind, fmt);
  // An empty `_locale` (none set yet) is not a valid tag; use the runtime default instead
  const localeCode = loc ?? presetLocale ?? (_locale || undefined);

  return new /** @type {any} */ (Formatter)(localeCode, { ...named, ...rest }).format(value);
};

/**
 * Shared implementation for {@link date} and {@link time}.
 * @param {'date' | 'time'} kind `'date'` or `'time'`, selects the format table and error label.
 * @param {Date} value The date to format.
 * @param {DateFormatOptions} [options] Formatting options.
 * @returns {string} The formatted string.
 * @throws {TypeError} If `value` is not a `Date` instance.
 */
const formatDateTimeValue = (kind, value, options = {}) => {
  if (!(value instanceof Date)) {
    throw new TypeError(`${kind}: value must be a Date instance (got ${typeof value})`);
  }

  return formatStandaloneValue(Intl.DateTimeFormat, kind, value, options);
};

/**
 * Format a date value as a localized date string.
 * @param {Date} value The date to format.
 * @param {DateFormatOptions} [options] Formatting options.
 * @returns {string} The formatted date string.
 * @throws {TypeError} If `value` is not a `Date` instance.
 */
const date = (value, options = {}) => formatDateTimeValue('date', value, options);
/**
 * Format a date value as a localized time string.
 * @param {Date} value The date to format.
 * @param {DateFormatOptions} [options] Formatting options.
 * @returns {string} The formatted time string.
 * @throws {TypeError} If `value` is not a `Date` instance.
 */
const time = (value, options = {}) => formatDateTimeValue('time', value, options);

/**
 * Format a number as a localized string.
 * @param {number | bigint} value The number to format.
 * @param {NumberFormatOptions} [options] Formatting options.
 * @returns {string} The formatted number string.
 * @throws {TypeError} If `value` is not a number or bigint.
 */
const number = (value, options = {}) => {
  if (typeof value !== 'number' && typeof value !== 'bigint') {
    throw new TypeError(`number: value must be a number or bigint (got ${typeof value})`);
  }

  return formatStandaloneValue(Intl.NumberFormat, 'number', value, options);
};

/**
 * Reset all internal state. Intended **only** for use in tests.
 * @internal
 */
const _reset = () => {
  _locale = '';
  requestedLocale = '';
  locales.splice(0);
  Object.keys(dictionary).forEach((k) => delete dictionary[k]);
  loaderQueue.clear();
  loaderPromises.clear();
  fallbackLocale = '';
  _resolvedFallback = '';
  missingMessageHandler = undefined;
  customFormats = {};
  customFunctions = {};
  messageFormats = undefined;
};

// Export all public API as named exports, and also alias `format` as `_` and `t` for convenience.
// We cannot use `export const` syntax for each symbol because the TypeScript conversion fails to
// export the comments with the functions.
export {
  format as _,
  _reset,
  addMessages,
  date,
  dictionary,
  format,
  getLocaleFromHash,
  getLocaleFromHostname,
  getLocaleFromNavigator,
  getLocaleFromPathname,
  getLocaleFromQueryString,
  init,
  isLoading,
  isRTL,
  json,
  locale,
  locales,
  number,
  register,
  registerMessageFunction,
  format as t,
  time,
  waitLocale,
};
